package io.github.diodeme.ji.security.secret;

import java.nio.file.Path;
import java.util.Objects;

/** Bounded adapter for systemd credential directories and Docker secret mounts. */
public final class MountedSecretSource implements SecretSource {
    private final Kind kind;
    private final Path root;
    private final FileSecretSource files;

    public MountedSecretSource(Kind kind, Path root) {
        if (kind != Kind.SYSTEMD_CREDENTIAL && kind != Kind.DOCKER_SECRET) {
            throw new IllegalArgumentException("mounted source kind must be systemd or Docker");
        }
        this.kind = kind;
        this.root = Objects.requireNonNull(root, "root").toAbsolutePath().normalize();
        this.files = new FileSecretSource();
    }

    public Kind kind() {
        return kind;
    }

    @Override
    public SecretValue read(String reference) {
        Path relative = Path.of(reference);
        if (relative.isAbsolute()) throw new SecurityException("mounted secret reference must be relative");
        Path resolved = root.resolve(relative).normalize();
        if (!resolved.startsWith(root)) throw new SecurityException("mounted secret reference escapes its root");
        return files.read(resolved.toString());
    }
}
